import{_ as e,o as t,c as d,a4 as r}from"./chunks/framework.BBs01uty.js";const u=JSON.parse('{"title":"机制五：Hook 系统（src/hooks.ts）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/hooks.md","filePath":"agent-cli/mechanisms/hooks.md"}'),c={name:"agent-cli/mechanisms/hooks.md"};function s(a,o,n,i,l,h){return t(),d("div",null,[...o[0]||(o[0]=[r('<h1 id="机制五-hook-系统-src-hooks-ts" tabindex="-1">机制五：Hook 系统（<code>src/hooks.ts</code>） <a class="header-anchor" href="#机制五-hook-系统-src-hooks-ts" aria-label="Permalink to &quot;机制五：Hook 系统（`src/hooks.ts`）&quot;">​</a></h1><blockquote><p>与 Claude Code 的 hook 同构（D32/D33）。让用户在工具调用的前后、提示词提交、回答结束时挂自己的 shell 命令。</p></blockquote><h2 id="_1-四个时机" tabindex="-1">1. 四个时机 <a class="header-anchor" href="#_1-四个时机" aria-label="Permalink to &quot;1. 四个时机&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时机</th><th>触发点</th><th>失败语义（D33）</th></tr></thead><tbody><tr><td><code>PreToolUse</code></td><td>executor 第 2 步（<strong>早于权限判定</strong>）</td><td>非 0 / 超时 → <strong>阻塞</strong>该工具调用（reason = stderr）</td></tr><tr><td><code>PostToolUse</code></td><td>executor 第 6 步（真正执行之后）</td><td>非 0 / 超时 → <strong>放行 + 告警</strong></td></tr><tr><td><code>UserPromptSubmit</code></td><td>用户提交提示词</td><td>非 0 / 超时 → <strong>放行 + 告警</strong></td></tr><tr><td><code>Stop</code></td><td>agent 回合结束</td><td>非 0 / 超时 → <strong>放行 + 告警</strong></td></tr></tbody></table><p><strong>明确不做 <code>SessionStart</code></strong>（D32）：它会改写已发送内容，违反 <strong>D23 前缀稳定性硬约束</strong>（见 <a href="./../architecture.html"><code>architecture.md</code></a> 不变量 1）。</p><h2 id="_2-协议" tabindex="-1">2. 协议 <a class="header-anchor" href="#_2-协议" aria-label="Permalink to &quot;2. 协议&quot;">​</a></h2><ul><li><strong>配置</strong>：内联 shell 命令（用户级 <code>~/.agent-cli/</code> 或项目级 <code>.agent-cli/hooks.json</code>）。</li><li><strong>输入</strong>：<code>stdin</code> 收 <code>JSON.stringify(payload) + &#39;\\n&#39;</code>（含工具名 / 参数 / 结果 / 耗时等，按时机不同）。</li><li><strong>输出</strong>： <ul><li><code>stdout</code>：仅 <code>PreToolUse</code> 消费，可回 <code>{decision:&#39;block&#39;, reason}</code> → 阻断工具调用；</li><li><code>stderr</code>：人读诊断，失败时作为 reason / 告警文案。</li></ul></li><li><strong>超时</strong>：<code>hookTimeoutMs = 10s</code>（D33：到点 SIGKILL 按失败处理；测试经注入调小做真实超时冒烟）。</li><li><strong>子进程结算</strong>（lesson 018）：以 <code>exit</code> 为结算信号 + 有界 flush 宽限，<strong>不无界等待被孙进程继承的管道</strong>——否则 hook 里 <code>cmd &amp;</code> 一挂就把 agent loop 无限挂起。已声明的副作用：hook 里的后台进程不跨调用存活。</li></ul><h2 id="_3-项目级-hook-与信任-fr-8" tabindex="-1">3. 项目级 hook 与信任（FR-8） <a class="header-anchor" href="#_3-项目级-hook-与信任-fr-8" aria-label="Permalink to &quot;3. 项目级 hook 与信任（FR-8）&quot;">​</a></h2><ul><li>项目级配置在 <code>&lt;仓库根&gt;/.agent-cli/hooks.json</code>（仓库根解析同权限文件，非 git 回落 cwd）。</li><li>首次加载弹<strong>信任框</strong>（列出全部命令、默认&quot;拒绝&quot;）；信任按 <strong>内容 hash</strong> 记入 <code>user-config.trustedHooks[projectRoot]</code>，hash 变化 → 重新询问。</li><li>未信任 → 项目级 hook 不加载（用户级不受影响），并有明确提示。</li><li><code>--yes</code> 不自动信任（信任请求带 <code>forced</code>，见 <a href="./interaction.html"><code>interaction.md</code></a>）。</li></ul><h2 id="_4-失败输出怎么到用户眼前" tabindex="-1">4. 失败输出怎么到用户眼前 <a class="header-anchor" href="#_4-失败输出怎么到用户眼前" aria-label="Permalink to &quot;4. 失败输出怎么到用户眼前&quot;">​</a></h2><ul><li><code>PreToolUse</code> 阻塞 → executor 返回 <code>{error: &#39;Hook 已阻止：…&#39;}</code> 给 LLM（可继续换策略）。</li><li>其余时机告警 → <code>index.ts</code> 的 <code>onHookWarning</code> → <code>ui.addInfo(&#39;[hook] …&#39;)</code>（TUI）/ <code>stderr</code>（非交互）。</li><li>告警文案与权限文件文本一样要过 <code>sanitizeForTerminal</code>（内容边界净化，见 <a href="./../architecture.html"><code>architecture.md</code></a> 不变量 6）。</li></ul><h2 id="_5-测试" tabindex="-1">5. 测试 <a class="header-anchor" href="#_5-测试" aria-label="Permalink to &quot;5. 测试&quot;">​</a></h2><p><code>hooks.test.ts</code>：四时机语义、block/warning、超时（注入短超时真实冒烟）、stdin/stdout 协议、项目级信任、<code>&amp;</code> 后台进程不挂起（lesson 018 回归）。</p>',13)])])}const k=e(c,[["render",s]]);export{u as __pageData,k as default};
